entries[102351] = { ["name"] = "Cenarischer Zauberschutz", ["text"] = "14.8% von Grundmana 40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBeschützt ein verbündetes Ziel, sodass jeglicher erlittener Schaden das Ziel im Verlauf von 6 Sek. alle 2 Sek. um 12349 heilt. Auslösung dieses Heileffekts zehrt 'Cenarischer Zauberschutz' auf. In allen Gestalten einsetzbar. Hält 30 Sek. lang an." }
