entries[102543] = { ["name"] = "Inkarnation: König des Dschungels", ["text"] = "Sofort 3 min Abklingzeit\nAktiviert 30 Sek. lang 'Inkarnation: König des Dschungels'.\n\nDiese verbesserte Katzengestalt gestattet den Einsatz sämtlicher Fähigkeiten, die normalerweise Verstohlenheit erfordern, gestattet den Einsatz von 'Schleichen' im Kampf und hebt die Positionsvoraussetzung von 'Verheeren' auf.\n\nWährend der Inkarnation könnt Ihr Euch beliebig in diese verbesserte Katzengestalt verwandeln." }
entries[102544] = { ["name"] = "Dämonengriff", ["text"] = "30 Meter Reichweite\nSofort 35 sek. Abklingzeit\nNutzt die Mächte unheiliger Energien, die alle Materie umgibt und bindet, um das Ziel zum Todesritter hin zu ziehen und es zu zwingen, ihn 3 Sek. lang anzugreifen." }
entries[102545] = { ["name"] = "Verheeren!", ["text"] = "45 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nVerheert das Ziel und verursacht so 950% Schaden plus 78 [ Infizierte Wunden : und verringert das Bewegungstempo des Ziels 12 Sek. lang um 50% ]. Gewährt 1 Combopunkt.\n\n'Verheeren' hat bei Zielen mit mehr als 80% Gesundheit eine um 50% erhöhte kritische Trefferchance." }
entries[102546] = { ["name"] = "Anspringen", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nSpringt das Ziel an, betäubt es 3 Sek. lang und verursacht im Verlauf von 18 Sek. insgesamt 4578 Blutungschaden. Gewährt 1 Combopunkt." }
entries[102547] = { ["name"] = "Schleichen", ["text"] = "Sofort 10 sek. Abklingzeit\nErmöglicht dem Druiden, sich außer Sicht zu stehlen und in einem verbesserten Verstohlenheitsmodus zu agieren, der jedoch das Bewegungstempo um 30% verringert. Hält an, bis die Aktion abgebrochen wird." }
