entries[102558] = { ["name"] = "Inkarnation: Sohn von Ursoc", ["text"] = "Sofort 3 min Abklingzeit\nWächter ( Hotfix - Passivfähigkeit )\nAktiviert 30 Sek. lang 'Inkarnation: Sohn von Ursoc'.\n\nDiese verbesserte Bärengestalt verringert die Abklingzeit aller Nahkampfschadensfähigkeiten sowie 'Knurren' auf 1,5 Sek.\n\nWährend der Inkarnation könnt Ihr Euch beliebig in diese verbesserte Bärengestalt verwandeln.\n\nGleichgewicht, Wildheit, Wiederherstellung\nAktiviert 30 Sek. lang 'Inkarnation: Sohn von Ursoc'.\n\nDiese verbesserte Bärengestalt verringert die Abklingzeit aller Nahkampfschadensfähigkeiten sowie 'Knurren' auf 1,5 Sek.\n\nWährend der Inkarnation könnt Ihr Euch beliebig in diese verbesserte Bärengestalt verwandeln." }
entries[102560] = { ["name"] = "Inkarnation: Erwählter der Elune", ["text"] = "Sofort 3 min Abklingzeit\nAktiviert 30 Sek. lang 'Inkarnation: Erwählter der Elune'.\n\nDiese verbesserte Mondkingestalt erhöht sämtlichen verursachten Arkan- und Naturschaden, während eine Mond- oder Sonnenfinsternis aktiv ist, um 25%.\n\nWährend der Inkarnation könnt Ihr Euch beliebig in diese verbesserte Mondkingestalt verwandeln." }
