entries[103103] = { ["name"] = "Bösartiger Griff", ["text"] = "1.5% von Grundmana , plus 1.5% pro Sekunde 40 Meter Reichweite\nKanalisiert (Wirken in 4 sek.)\nGebrechen ( Hotfix - Passivfähigkeit )\nBindet das Ziel in Zwielicht, das im Verlauf von 4 Sek. insgesamt 564 Schattenschaden verursacht.\n\nAlle 1 Sek., wenn 'Bösartiger Griff' Schaden verursacht, verursachen alle Eure anderen regelmäßigen Gebrechenszauber sofort 50% ihres normalen regelmäßigen Schadens.\n\nBindet das Ziel in Zwielicht, das im Verlauf von 4 Sek. insgesamt 564 Schattenschaden verursacht.\n\nAlle 1 Sek., wenn 'Bösartiger Griff' Schaden verursacht, verursachen alle Eure anderen regelmäßigen Gebrechenszauber sofort 30% ihres normalen regelmäßigen Schadens." }
