entries[103128] = { ["name"] = "Leerwandler: Leiden", ["text"] = "Lehrt Euren Leerwandler den Zauber 'Leiden'.\n\nLeiden Spezialfähigkeit 40 Energie 30 m Reichweite\nSofort 10 Sek. Abklingzeit Requires Warlock\nRequires level 15 Der Leerwandler verspottet das Ziel, damit es ihn angreift. Erhöht außerdem die danach gegen das Ziel erzeugte Bedrohung für 5 Sek. um 200%.\n\nAutomatisches Wirken:\nVerspottet das aktuelle Ziel, wenn es den Leerwandler nicht angreift und verspottet alle Gegner, die den Meister angreifen.\n\n(Mit Rechtsklick umschalten)" }
entries[103129] = { ["name"] = "Teufelswache: Verfolgung", ["text"] = "Lehrt Eure Teufelswache die Fähigkeit 'Verfolgung'.\n\nDie Teufelswache stürmt auf einen Gegner zu und verursacht sofort Waffenschaden, zudem wird das Bewegungstempo der Teufelswache 6 Sek. lang um 30% erhöht." }
entries[103130] = { ["name"] = "Leerwandler: Schattenschild", ["text"] = "Lehrt Euren Leerwandler den Zauber 'Schattenschild'.\n\nSchattenschild Spezialfähigkeit 60 Energie\nSofort 10 Sek. Abklingzeit Requires level 28 Hüllt den Leerwandler in Schattenenergien, die seinen erlittenen körperlichen Schaden 30 Sek. lang um 60% verringern.\n\nJedes Mal, wenn der Leerwandler von einem Angriff getroffen wird, wird eine Schattenexplosion ausgelöst, die dem Angreifer 1115 Schattenschaden zufügt, die Kraft des Schattenschilds jedoch um 20% verringert.\n\nAutomatisches Wirken:\nWird genutzt, sobald der Leerwandler angegriffen wird.\n\n(Mit Rechtsklick umschalten)" }
entries[103131] = { ["name"] = "Teufelswache: Axtwurf", ["text"] = "Lehrt Eure Teufelswache die Fähigkeit 'Axtwurf'.\n\nDie Teufelswache schleudert ihre Axt, wodurch das Ziel 4 Sek. lang betäubt wird." }
entries[103133] = { ["name"] = "Wichtel: Flüchten", ["text"] = "Lehrt Euren Wichtel die Fähigkeit 'Flüchten'.\n\nFlüchten Spezialfähigkeit 20 Energie 40 m Reichweite\nSofort 20 Sek. Abklingzeit Requires level 33 Flüchtet zum Meister. Durch die Fähigkeit 'Flüchten' werden alle Betäubungs- und Bewegungsunfähigkeitseffekte entfernt." }
entries[103134] = { ["name"] = "Teufelswache: Teufelssturm", ["text"] = "Lehrt Eure Teufelswache die Fähigkeit 'Teufelssturm'.\n\nEure Teufelswache vollführt waghalsige Angriffe, die allen Zielen im Umkreis von 8 Metern 6 Sek. lang alle 1 Sek. 100% Waffenschaden zufügen.\n\nWährend des Teufelssturms kann die Teufelswache keine weiteren Fähigkeiten einsetzen." }
entries[103135] = { ["name"] = "Teufelsjäger: Zaubersperre", ["text"] = "Lehrt Euren Teufelsjäger den Zauber 'Zaubersperre'.\n\nZaubersperre Spezialfähigkeit 20 Energie 40 m Reichweite\nSofort 24 Sek. Abklingzeit Requires level 50 Bringt den Gegner 3 Sek. lang zum Schweigen. Wenn der Zauber gegen einen zaubernden Gegner eingesetzt wird, verhindert er für 6 Sek., dass erneut ein Zauber dieser Art gewirkt werden kann." }
entries[103136] = { ["name"] = "Teufelsjäger: Magie verschlingen" }
entries[103138] = { ["name"] = "Flying Colors: Quest Complete" }
entries[103139] = { ["name"] = "Sukkubus: Verführung", ["text"] = "Lehrt Euren Sukkubus den Zauber 'Verführung'.\n\nVerführung Spezialfähigkeit 20 Energie 30 m Reichweite Wirken in 1.7 Sek.\nRequires level 20 Verführt das Ziel und verhindert dadurch bis zu 30 Sek. lang alle Aktionen. Jeglicher erlittene Schaden wird den Effekt aufheben. Funktioniert nur gegen Humanoide.\n\nAutomatisches Wirken:\nWird auf Ziele gewirkt, die den Meister angreifen, betäuben, zum Schweigen bringen oder in Furcht versetzen.\n\n(Mit Rechtsklick umschalten)" }
entries[103140] = { ["name"] = "Sukkubus: Geringe Unsichtbarkeit", ["text"] = "Lehrt Euren Sukkubus den Zauber 'Geringe Unsichtbarkeit'.\n\nGeringe Unsichtbarkeit Spezialfähigkeit 20 Energie\n\nSofort\nRequires Warlock\nRequires level 32 Verleiht dem Sukkubus oder Inkubus bis zu 5 Min. lang geringe Unsichtbarkeit. Der Zauber kann nur außerhalb des Kampfes verwendet werden.\n\nAutomatisches Wirken:\nWird gewirkt, sobald der Sukkubus oder Inkubus den Kampf verlässt.\n\n(Mit Rechtsklick umschalten)" }
entries[103141] = { ["name"] = "Sukkubus: Peitschen" }
entries[103142] = { ["name"] = "Leerwandler: Schattenbollwerk", ["text"] = "Lehrt Euren Leerwandler den Zauber 'Schattenbollwerk'.\n\nSchattenbollwerk Spezialfähigkeit 50 Energie Unbegrenzte Reichweite\nSofort 2 Min. Abklingzeit Requires Warlock\nRequires level 55 Gewährt dem Leerwandler 20 Sek. lang 30% seiner maximalen Gesundheit.\n\nAutomatisches Wirken:\nWird gewirkt, wenn die Gesundheit unter 20% sinkt.\n\n(Mit Rechtsklick umschalten)" }
