entries[103150] = { ["name"] = "Wichtel: Magie versengen", ["text"] = "Lehrt Euren Wichtel den Zauber 'Magie herausbrennen'.\n\nMagie versengen Spezialfähigkeit 40 Energie 30 m Reichweite\nSofort 10 Sek. Abklingzeit Requires level 68 Brennt schädigende Magie aus dem Ziel heraus und entfernt 1 schädlichen Zauber von einem Verbündeten.\n\nAutomatisches Wirken:\nWird auf den Meister gewirkt, wenn er aufgrund magischer Effekte keine Zauber wirken kann.\n\n(Mit Rechtsklick umschalten)" }
